using System;
using System.Collections.Generic;
using DenTinh.Core;
public static class SimulationTests {
    static int passed,failed;
    static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static Simulation Game(string hero="hoavi"){Simulation g=new Simulation(CatalogData.Create(),hero,71426);g.Tutorial=5;return g;}
    static EnemyState Dummy(Simulation g,V2 at,float hp){EnemyState e=g.Spawn("slime",at,false);e.hp=e.maxHp=hp;e.speed=0;e.damage=0;return e;}
    static void Tick(Simulation g,int count){for(int i=0;i<count;i++)g.Tick(1/60f);}
    public static int Main(){
        Test("Shared catalog has four original heroes, thirteen weapons and twelve relics",delegate{ContentDatabase c=CatalogData.Create();Assert(c.heroes.Length==4&&c.weapons.Length==13&&c.relics.Length==12,"catalog size");Assert(c.Hero("hoavi").name=="HoaVi","HoaVi missing");Assert(c.Weapon("shadow-crescent").kind=="shadow","Shadow weapon missing");});
        Test("All heroes can shoot and damage an enemy",delegate{foreach(HeroDef h in CatalogData.Create().heroes){Simulation g=Game(h.id);g.Enemies.Clear();g.Props.Clear();g.Player.position=new V2(25,20);EnemyState e=Dummy(g,new V2(28,20),500);g.Input=new GameInput{aim=e.position,attack=true};Tick(g,90);Assert(e.hp<500,h.id+" cannot hit");}});
        Test("Magazine, reload and weapon switch preserve separate ammunition",delegate{Simulation g=Game();int clip=g.Active.ammo;g.Player.fireTimer=0;Assert(g.Fire(),"first shot");Assert(g.Active.ammo==clip-1,"ammo not spent");g.Swap();Assert(g.Active.ammo==g.Weapon.clip,"second slot changed");g.Swap();Assert(g.Reload(),"reload failed");Tick(g,100);Assert(g.Active.ammo==g.Weapon.clip,"reload did not refill");});
        Test("HoaVi Mã Lệnh charges from hits and Debug consumes stacks",delegate{Simulation g=Game();g.Enemies.Clear();g.Props.Clear();g.Player.position=new V2(25,20);EnemyState e=Dummy(g,new V2(27,20),900);g.DamageEnemy(e,10,true);Assert(g.Player.code==1,"passive");g.Player.code=8;g.Input=new GameInput{aim=e.position};Assert(g.Skill("q"),"debug");Assert(g.Player.code==0&&g.Player.qTimer<g.Hero.qCd,"stack consumption");Assert(g.Player.mp==76,"mana");});
        Test("Firewall absorbs hits and destroys hostile projectiles",delegate{Simulation g=Game();g.Enemies.Clear();g.Props.Clear();g.Player.position=new V2(25,20);g.Player.hp=40;Assert(g.Skill("e"),"firewall");Assert(g.Player.hp==58&&g.Player.shield==32,"shield / heal");g.DamagePlayer(10);Assert(g.Player.hp==58&&g.Player.shield==22,"shield hit");g.Shoot(new V2(26,20),3.14159f,1,20,false,"orb","#f00");Tick(g,20);Assert(g.Bullets.Count==0,"firewall did not block");});
        Test("Overclock is bounded and drones do not recharge their own ultimate",delegate{Simulation g=Game();g.Enemies.Clear();g.Props.Clear();g.Player.position=new V2(25,20);Dummy(g,new V2(28,20),5000);g.Player.ult=100;Assert(g.Skill("r"),"overclock");Assert(!g.Skill("r"),"double ultimate");Tick(g,269);Assert(g.Player.ultIntro!=null&&g.Player.overclock==0,"released early");Tick(g,2);Assert(g.Player.ultIntro==null&&g.Player.overclock>6.9f,"intro release");Assert(Math.Abs(g.Player.rCd-(18-271/60f))<.001f,"cooldown timing");Tick(g,1081);Assert(g.Player.overclock==0,"overclock did not expire");});
        Test("All four ultimates including following storms never recharge themselves",delegate{foreach(HeroDef h in CatalogData.Create().heroes){Simulation g=Game(h.id);g.Enemies.Clear();g.Props.Clear();g.Player.position=new V2(25,20);Dummy(g,new V2(28,20),10000);g.Player.ult=100;g.Skill("r");Tick(g,400);Assert(Math.Abs(g.Player.rCd-(h.rCd-400/60f))<.002f,h.id+" cooldown changed by damage");}});
        Test("Dash immunity and cooldown prevent repeated dodging",delegate{Simulation g=Game();g.Player.position=new V2(25,20);g.Input=new GameInput{move=new V2(1,0)};Assert(g.Dash(),"dash");float hp=g.Player.hp;g.DamagePlayer(50);Assert(g.Player.hp==hp,"immunity");Assert(!g.Dash(),"cooldown");Tick(g,80);Assert(g.Dash(),"cooldown recovery");});
        Test("Movement collision and boundaries remain solid",delegate{Simulation g=Game();g.Player.position=new V2(.7f,20);g.Input=new GameInput{move=new V2(-1,0)};Tick(g,90);Assert(g.Player.position.x>=.6f,"outside world");});
        Test("Relics alter projectile count and dash damage",delegate{Simulation g=Game();g.Enemies.Clear();g.Props.Clear();g.Player.position=new V2(25,20);int shots=g.Weapon.shots;g.ApplyRelic("split",false);g.Fire();Assert(g.Bullets.Count==shots+1,"split");g.ApplyRelic("dashshock",false);EnemyState e=Dummy(g,new V2(26,20),500);g.Dash();Assert(e.hp<500,"dashshock");});
        Test("Three seals require three distinct challenges",delegate{Simulation g=Game();g.Player.position=g.Shrines[1].position;Assert(g.Interact()&&!g.Shrines[1].active&&g.Shrines[1].started,"defense gate");g.Player.position=new V2(29,37);Assert(!g.Interact()&&!g.BossStarted,"boss gate");g.Player.position=g.Shrines[2].position;Assert(g.Interact(),"forge start");Assert(g.Shrines[2].enemies.Count==3,"forge cores");foreach(EnemyState e in g.Enemies.ToArray())if(e.challenge=="tro")g.DamageEnemy(e,10000,false);g.Tick(.02f);Assert(g.Shrines[2].complete,"forge completion");Assert(g.Interact()&&g.Shrines[2].active,"forge reward");});
        Test("Defense failure is retryable without corrupting shrine progress",delegate{Simulation g=Game();Shrine s=g.Shrines[1];g.StartChallenge(s);s.hp=0;g.Tick(.02f);Assert(!s.started&&!s.active&&s.hp==100,"failure reset");Assert(g.StartChallenge(s),"retry");});
        Test("Boss shield needs destructible roots, then third phase adds hazards",delegate{Simulation g=Game();foreach(Shrine s in g.Shrines)s.active=true;g.Player.position=new V2(29,37);Assert(g.Interact(),"start boss");EnemyState b=g.Enemies.Find(e=>e.type=="boss");b.hp=b.maxHp*.6f;g.Tick(.02f);Assert(g.Enemies.FindAll(e=>e.root&&e.alive).Count==3,"roots missing");float hp=b.hp;g.DamageEnemy(b,100,false);Assert(hp-b.hp<50,"root shield ineffective");foreach(EnemyState e in g.Enemies.ToArray())if(e.root)g.DamageEnemy(e,10000,false);b.hp=b.maxHp*.2f;g.Tick(.02f);Assert(b.phase==3&&g.Dangers.Count>0,"third phase");});
        Test("Save snapshot restores weapons, relics, health and activated seals",delegate{Simulation g=Game();g.Player.hp=44;g.Player.gold=123;g.Active.level=3;g.ApplyRelic("chain",false);g.Shrines[0].active=true;Simulation r=Simulation.Restore(CatalogData.Create(),g.Capture());Assert(r.Hero.id=="hoavi"&&r.Player.hp==44&&r.Player.gold==123,"player state");Assert(r.Active.level==3&&r.Player.Has("chain")&&r.Shrines[0].active,"progress");bool invalid=false;try{Simulation.Restore(CatalogData.Create(),new RunSave());}catch(ArgumentException){invalid=true;}Assert(invalid,"invalid save accepted");});
        Test("Save retains unclaimed level rewards and a chest opened before the tutorial step",delegate{Simulation g=Game();g.Tutorial=0;Loot chest=g.Drops.Find(l=>l.kind=="chest");g.Player.position=chest.position;g.Interact();EnemyState e=Dummy(g,g.Player.position+new V2(1,0),10);e.xp=500;g.DamageEnemy(e,100,false);g.Tutorial=4;Assert(g.PendingLevels>0,"level reward missing");Simulation r=Simulation.Restore(CatalogData.Create(),g.Capture());Assert(r.PendingLevels==g.PendingLevels,"unclaimed rewards lost");r.Tick(.02f);Assert(r.Tutorial==5,"early opened chest was forgotten");});
        Test("Respawn keeps progression, resets failed challenges and charges 10 percent",delegate{Simulation g=Game();g.Player.gold=101;g.Shrines[0].active=true;g.Player.position=new V2(25,20);g.DamagePlayer(10000);Assert(g.Dead,"death");g.Respawn();Assert(!g.Dead&&g.Player.gold==90&&g.Shrines[0].active,"respawn progress");});
        Test("New seeds vary world and New Game Plus scales enemies",delegate{Simulation a=Game(),b=new Simulation(CatalogData.Create(),"hoavi",9321,2);Assert(a.Props[0].position.x!=b.Props[0].position.x,"seed variation");Assert(b.Enemies[0].maxHp>a.Enemies[0].maxHp,"cycle scaling");});
        Console.WriteLine(passed+"/"+(passed+failed)+" checks passed");return failed==0?0:1;
    }
}
